-- Datos de prueba de FINAZAPP (mercado argentino, relevados en octubre de 2026).
-- Se edita directamente: es la unica fuente de los datos de prueba. Mantenerlo idempotente.
-- Ejecutar DESPUES de script_bd.sql. Es idempotente (se puede correr mas de una vez).
-- No ejecutar sobre la base de tests (TpCatedraIDS_Test): algunos tests parten de catalogos vacios.
-- Usuario de prueba: los datos personales se asignan al usuario "user" ya sembrado por script_bd.sql.

USE [TpCatedraIDS];
GO
SET QUOTED_IDENTIFIER ON;
SET NOCOUNT ON;
GO

DECLARE @p INT;
DECLARE @uid INT = (SELECT Id FROM dbo.Usuarios WHERE Username = N'user');
IF @uid IS NULL THROW 50001, 'No existe el usuario user: ejecutar script_bd.sql antes.', 1;

BEGIN TRY
BEGIN TRANSACTION;

