-- Datos del usuario de prueba (user) -------------------------------------
IF NOT EXISTS (SELECT 1 FROM dbo.Categoria WHERE Nombre = N'Gimnasio' AND UsuarioId = @uid) INSERT INTO dbo.Categoria (Nombre, UsuarioId) VALUES (N'Gimnasio', @uid);
IF NOT EXISTS (SELECT 1 FROM dbo.Categoria WHERE Nombre = N'Salidas con amigos' AND UsuarioId = @uid) INSERT INTO dbo.Categoria (Nombre, UsuarioId) VALUES (N'Salidas con amigos', @uid);
IF NOT EXISTS (SELECT 1 FROM dbo.Categoria WHERE Nombre = N'Freelance' AND UsuarioId = @uid) INSERT INTO dbo.Categoria (Nombre, UsuarioId) VALUES (N'Freelance', @uid);
IF NOT EXISTS (SELECT 1 FROM dbo.Categoria WHERE Nombre = N'Café y meriendas' AND UsuarioId = @uid) INSERT INTO dbo.Categoria (Nombre, UsuarioId) VALUES (N'Café y meriendas', @uid);
IF NOT EXISTS (SELECT 1 FROM dbo.Categoria WHERE Nombre = N'Donaciones' AND UsuarioId = @uid) INSERT INTO dbo.Categoria (Nombre, UsuarioId) VALUES (N'Donaciones', @uid);
IF NOT EXISTS (SELECT 1 FROM dbo.Categoria WHERE Nombre = N'Mantenimiento del hogar' AND UsuarioId = @uid) INSERT INTO dbo.Categoria (Nombre, UsuarioId) VALUES (N'Mantenimiento del hogar', @uid);
IF NOT EXISTS (SELECT 1 FROM dbo.CuentaFinanciera WHERE UsuarioId = @uid AND Alias = N'Sueldo Galicia') INSERT INTO dbo.CuentaFinanciera (UsuarioId, EntidadFinancieraId, Alias, Tipo, CredencialesCifradas) SELECT @uid, Id, N'Sueldo Galicia', N'CajaAhorro', NULL FROM dbo.EntidadFinanciera WHERE Nombre = N'Galicia';
INSERT INTO dbo.CuentaFinancieraMedioPagoEntidad (CuentaFinancieraId, MedioPagoEntidadId) SELECT cf.Id, mpe.Id FROM dbo.CuentaFinanciera cf JOIN dbo.EntidadFinanciera e ON e.Id = cf.EntidadFinancieraId JOIN dbo.MedioPagoEntidad mpe ON mpe.EntidadFinancieraId = e.Id JOIN dbo.MedioPago mp ON mp.Id = mpe.MedioPagoId WHERE cf.UsuarioId = @uid AND cf.Alias = N'Sueldo Galicia' AND mp.Tipo = N'TarjetaDebito' AND mp.Marca = N'Visa' AND mpe.Segmento IS NULL AND NOT EXISTS (SELECT 1 FROM dbo.CuentaFinancieraMedioPagoEntidad x WHERE x.CuentaFinancieraId = cf.Id AND x.MedioPagoEntidadId = mpe.Id);
