SELECT t.Tabla, t.Filas FROM (VALUES
    (N'RubroComercio', (SELECT COUNT(*) FROM dbo.RubroComercio)),
    (N'CategoriaProducto', (SELECT COUNT(*) FROM dbo.CategoriaProducto)),
    (N'Categoria', (SELECT COUNT(*) FROM dbo.Categoria)),
    (N'EntidadFinanciera', (SELECT COUNT(*) FROM dbo.EntidadFinanciera)),
    (N'MedioPago', (SELECT COUNT(*) FROM dbo.MedioPago)),
    (N'MedioPagoEntidad', (SELECT COUNT(*) FROM dbo.MedioPagoEntidad)),
    (N'Comercio', (SELECT COUNT(*) FROM dbo.Comercio)),
    (N'Producto', (SELECT COUNT(*) FROM dbo.Producto)),
    (N'ComercioProducto', (SELECT COUNT(*) FROM dbo.ComercioProducto)),
    (N'Promocion', (SELECT COUNT(*) FROM dbo.Promocion)),
    (N'PromocionDiaSemana', (SELECT COUNT(*) FROM dbo.PromocionDiaSemana)),
