    (N'PromocionMedioPago', (SELECT COUNT(*) FROM dbo.PromocionMedioPago)),
    (N'PromocionSegmento', (SELECT COUNT(*) FROM dbo.PromocionSegmento)),
    (N'PromocionProducto', (SELECT COUNT(*) FROM dbo.PromocionProducto)),
    (N'PromocionCategoriaProducto', (SELECT COUNT(*) FROM dbo.PromocionCategoriaProducto)),
    (N'PromocionComercio', (SELECT COUNT(*) FROM dbo.PromocionComercio)),
    (N'PromocionRubroComercio', (SELECT COUNT(*) FROM dbo.PromocionRubroComercio)),
    (N'CuentaFinanciera', (SELECT COUNT(*) FROM dbo.CuentaFinanciera)),
