    (N'Movimiento', (SELECT COUNT(*) FROM dbo.Movimiento)),
    (N'ReglaCategorizacion', (SELECT COUNT(*) FROM dbo.ReglaCategorizacion)),
    (N'ComercioReglaCategorizacion', (SELECT COUNT(*) FROM dbo.ComercioReglaCategorizacion))
